const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const africa = ee.FeatureCollection('FAO/GAUL_0/2015/Africa');
    const geometry = africa.geometry();

    // Define the two periods
    const period1_start_year = 2004;
    const period1_end_year = 2007;
    const period2_start_year = 2016;
    const period2_end_year = 2019;

    const scale = 5000; // Increased scale to avoid timeout, ESA CCI LC resolution is ~300m
    const maxPixels = 1e10; // Allow more pixels for large area

    // Function to get cropland area for a specific year
    const getCroplandArea = (year) => {
      const collection = ee.ImageCollection('ESA/CCI/LC/L4_LCCS_Map')
        .filterDate(`${year}-01-01`, `${year}-12-31`);

      if (collection.size().getInfo() === 0) {
        console.log(`No ESA CCI LC image found for year ${year}.`);
        return null;
      }

      const image = ee.Image(collection.first());
      const lccs_class = image.select('lccs_class');

      // Cropland classes: 10 (rainfed), 11 (irrigated), 12 (mixed)
      const cropland = lccs_class.eq(10).or(lccs_class.eq(11)).or(lccs_class.eq(12));

      // Calculate area of cropland pixels.
      // Each pixel is approx 300m x 300m = 90000 sq meters.
      const areaImage = cropland.multiply(ee.Image.pixelArea()); // Area in square meters

      const area_m2 = areaImage.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: maxPixels,
        tileScale: 16 // Increased tileScale for large regions
      }).get('sum');

      return area_m2;
    };

    // Calculate cropland area for the start and end of Period 1
    console.log(`Processing Period 1: ${period1_start_year}-${period1_end_year}`);
    const area1_start_val = await getCroplandArea(period1_start_year);
    const area1_end_val = await getCroplandArea(period1_end_year);

    if (area1_start_val === null || area1_end_val === null) {
      console.log("C1: No data for one or more years in Period 1.");
      console.log("C1");
      return;
    }

    const area1_start = area1_start_val.getInfo();
    const area1_end = area1_end_val.getInfo();

    if (area1_start === 0 && area1_end === 0) {
      console.log(`Period 1: Cropland area for ${period1_start_year} is 0.00 km², ${period1_end_year} is 0.00 km². (Potentially C2 for this specific calculation if this is unexpected for Africa, but it's likely a real 0 if there are no valid pixels for calculation after all processing)`);
    } else if (area1_start === null || area1_end === null) {
      console.log("C3: Calculation failure for Period 1 cropland area.");
      console.log("C3");
      return;
    }

    // Calculate cropland area for the start and end of Period 2
    console.log(`Processing Period 2: ${period2_start_year}-${period2_end_year}`);
    const area2_start_val = await getCroplandArea(period2_start_year);
    const area2_end_val = await getCroplandArea(period2_end_year);

    if (area2_start_val === null || area2_end_val === null) {
      console.log("C1: No data for one or more years in Period 2.");
      console.log("C1");
      return;
    }

    const area2_start = area2_start_val.getInfo();
    const area2_end = area2_end_val.getInfo();

    if (area2_start === 0 && area2_end === 0) {
      console.log(`Period 2: Cropland area for ${period2_start_year} is 0.00 km², ${period2_end_year} is 0.00 km². (Potentially C2 for this specific calculation if this is unexpected for Africa, but it's likely a real 0 if there are no valid pixels for calculation after all processing)`);
    } else if (area2_start === null || area2_end === null) {
      console.log("C3: Calculation failure for Period 2 cropland area.");
      console.log("C3");
      return;
    }

    // Convert areas to km^2 for better readability
    const area1_start_km2 = area1_start / 1e6;
    const area1_end_km2 = area1_end / 1e6;
    const area2_start_km2 = area2_start / 1e6;
    const area2_end_km2 = area2_end / 1e6;

    // Calculate cropland expansion for each period
    const expansion1 = area1_end_km2 - area1_start_km2;
    const duration1 = period1_end_year - period1_start_year;
    const rate1 = expansion1 / duration1;

    const expansion2 = area2_end_km2 - area2_start_km2;
    const duration2 = period2_end_year - period2_start_year;
    const rate2 = expansion2 / duration2;

    if (isNaN(rate1) || isNaN(rate2) || rate1 === null || rate2 === null) {
      console.log("C3: Calculation failure: result is NaN or Null.");
      console.log("C3");
      return;
    }

    console.log(`P1 (${period1_start_year}-${period1_end_year}) - Start: ${area1_start_km2.toFixed(2)} km², End: ${area1_end_km2.toFixed(2)} km², Expansion: ${expansion1.toFixed(2)} km², Rate: ${rate1.toFixed(2)} km²/year`);
    console.log(`P2 (${period2_start_year}-${period2_end_year}) - Start: ${area2_start_km2.toFixed(2)} km², End: ${area2_end_km2.toFixed(2)} km², Expansion: ${expansion2.toFixed(2)} km², Rate: ${rate2.toFixed(2)} km²/year`);

    // Compare the rates
    if (rate2 < rate1) {
      console.log("A"); // Cropland expansion slowed
    } else {
      console.log("B"); // Cropland expansion did not slow (or increased/stayed same)
    }

  } catch (error) {
    console.error("D: An unexpected error occurred:", error);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
